    anoms=[(r,c) for r in range(H) for c in range(W) if I[r][c]!=bg and I[r][c]!=barc]
    for (r,c) in anoms:
        O[r][c]=4
        hv=[(a,lo,hi) for a,lo,hi in hsegs if lo<=c<=hi]
        vv=[(a,lo,hi) for a,lo,hi in vsegs if lo<=r<=hi]
        if hv:
            ha=a0=hv[0]; lo0,hi0=ha[1],ha[2]
            te=min(lo0,hi0,key=lambda e:abs(e-c))
            step=1 if c<te else -1
            cc=c+step
            while 0<=cc<W:
                if I[r][cc]!=barc: O[r][cc]=anc
                cc+=step
            rel=c-lo0
            # target anchor: same rel within every V-seg (if rel fits); fill entire target row
            for va,tl,th in vsegs:
                if tl<=tl+rel<=th:
                    tr=tl+rel
                    for cc2 in range(W):
                        if I[tr][cc2]!=barc: O[tr][cc2]=anc
        elif vv:
            va,lo0,hi0=vv[0]
            te=min(lo0,hi0,key=lambda e:abs(e-r))
            step=1 if r<te else -1
            rr=r+step
            while 0<=rr<H:
                if I[rr][c]!=barc: O[rr][c]=anc
                rr+=step
            rel=r-lo0
            for ha,tl,th in hsegs:
                if tl<=tl+rel<=th:
